insert  into `dbdocssubtables`(`subTableId`,`languageId`,`subTableName`,`subTableTemplate`) values (16,0,'Quest Status','Value|Status Flag|<Notes\r\n0|QUEST&#95;STATUS&#95;NONE|Quest isn\'t shown in quest list - default value\r\n1|QUEST&#95;STATUS&#95;COMPLETE|Quest has been completed.\r\n2|QUEST&#95;STATUS&#95;UNAVAILABLE|Quest is unavailable to the character.\r\n3|QUEST&#95;STATUS&#95;INCOMPLETE|Quest is active in quest log but incomplete\r\n4|QUEST&#95;STATUS&#95;AVAILABLE|Quest is available to be taken by character');
insert  into `dbdocssubtables`(`subTableId`,`languageId`,`subTableName`,`subTableTemplate`) values (17,0,'Reputation Flags','Flag|Flag Name|<Notes\r\n1|FACTION&#95;FLAG&#95;VISIBLE|Displayed in the reputation tab\r\n2|FACTION&#95;FLAG&#95;AT&#95;WAR|Active when the player sets the at war checkbox\r\n4|FACTION&#95;FLAG&#95;UNKNOWN|UNKNOWN\r\n8|FACTION&#95;FLAG&#95;INVISIBLE|Not Displayed in the reputation tab\r\n16|FACTION&#95;FLAG&#95;OWN&#95;TEAM|OWN&#95;TEAM\r\n32|FACTION&#95;FLAG&#95;INACTIVE|INACTIVE');
