insert  into `dbdocssubtables`(`subTableId`,`languageId`,`subTableName`,`subTableTemplate`) values (20,0,'Guild Event Types','Value|<Meaning\r\n1|GUILD_EVENT_LOG_INVITE_PLAYER\r\n2|GUILD_EVENT_LOG_JOIN_GUILD\r\n3|GUILD_EVENT_LOG_PROMOTE_PLAYER\r\n4|GUILD_EVENT_LOG_DEMOTE_PLAYER\r\n5|GUILD_EVENT_LOG_UNINVITE_PLAYER\r\n6|GUILD_EVENT_LOG_LEAVE_GUILD');
insert  into `dbdocssubtables`(`subTableId`,`languageId`,`subTableName`,`subTableTemplate`) values (21,0,'Guild Rights','Flag|Flag Name|<Meaning\r\n64|GR&#95;RIGHT&#95;EMPTY|Having just this flag by itself is equivalent to having no rights at all.\r\n65|GR&#95;RIGHT&#95;GCHATLISTEN|Player can read messages in the guild general chat channel.\r\n66|GR&#95;RIGHT&#95;GCHATSPEAK|Player can type messages in the guild general chat channel.\r\n68|GR&#95;RIGHT&#95;OFFCHATLISTEN|Player can read messages in the guild officers channel.\r\n72|GR&#95;RIGHT&#95;OFFCHATSPEAK|Player can type messages in the guild officers channel.\r\n80|GR&#95;RIGHT&#95;INVITE|Can invite other players to guild.\r\n80|GR&#95;RIGHT&#95;INVITE|Can invite other players to guild.\r\n96|GR&#95;RIGHT&#95;REMOVE|Can kick other players out of guild.\r\n192|GR&#95;RIGHT&#95;PROMOTE|Can promote other players.\r\n320|GR&#95;RIGHT&#95;DEMOTE|Can demote other players.\r\n4160|GR&#95;RIGHT&#95;SETMOTD|Can change the guild message of the day.\r\n8256|GR&#95;RIGHT&#95;EPNOTE|Can edit other players\' personal notes.\r\n16448|GR&#95;RIGHT&#95;VIEWOFFNOTE|Can view the officer notes of other players.\r\n32832|GR&#95;RIGHT&#95;EOFFNOTE|Can edit officer notes of other players.\r\n61951|GR&#95;RIGHT&#95;ALL|Has all of the rights.');
insert  into `dbdocssubtables`(`subTableId`,`languageId`,`subTableName`,`subTableTemplate`) values (22,0,'Item Instance Data','Index|Flag Name|<Meaning\r\n0|OBJECT&#95;FIELD&#95;GUID|Item GUID\r\n2|OBJECT&#95;FIELD&#95;TYPE|Should be 3 (TYPE&#95;OBJECT + TYPE&#95;ITEM)\r\n3|OBJECT&#95;FIELD&#95;ENTRY|Entry\r\n4|OBJECT&#95;FIELD&#95;SCALE&#95;X|1.0\r\n5|OBJECT&#95;FIELD&#95;PADDING|Some padding, need more info here.\r\n6|ITEM&#95;FIELD&#95;OWNER|owner&#95;guid\r\n8|ITEM&#95;FIELD&#95;CONTAINED|If the item is in a bag, the GUID of the bag item; otherwise owner GUID.\r\n10|ITEM&#95;FIELD&#95;CREATOR|GUID of character who created the item.\r\n12|ITEM&#95;FIELD&#95;GIFTCREATOR|GUID of character who created the \"item\". (See character_gifts.item_guid).\r\n14|ITEM&#95;FIELD&#95;STACK&#95;COUNT|Current number of item copies in the stack.\r\n15|ITEM&#95;FIELD&#95;DURATION|Current duration (in milliseconds)\r\n16|ITEM&#95;FIELD&#95;SPELL&#95;CHARGES|Current Number of charges left in the item\r\n21|ITEM&#95;FIELD&#95;FLAGS|Flags from \"item&#95;template\" (See Item_template.flags).\r\n22|ITEM&#95;FIELD&#95;ENCHANTMENT|Unknown\r\n55|ITEM&#95;FIELD&#95;PROPERTY&#95;SEED|Also called ITEM&#95;FIELD&#95;SUFFIX&#95;FACTOR\r\n56|ITEM&#95;FIELD&#95;RANDOM&#95;PROPERTIES&#95;ID|Unknown\r\n57|ITEM&#95;FIELD&#95;ITEM&#95;TEXT&#95;ID|Text id used and shown by the item.\r\n58|ITEM&#95;FIELD&#95;DURABILITY|Current item durability.\r\n59|ITEM&#95;FIELD&#95;MAXDURABILITY|Maximum item durability.');
